package dev.groundburst.world;

import dev.groundburst.GroundBurst;
import net.minecraft.core.registries.Registries;
import net.minecraft.world.level.levelgen.placement.PlacementModifierType;
import dev.groundburst.legacy.DeferredHolder;
import dev.groundburst.legacy.DeferredRegister;

/** Worldgen code registrations. The features themselves are data (generated by {@code GBWorldgenData}). */
public final class GBWorldgen {
    public static final DeferredRegister<PlacementModifierType<?>> PLACEMENT_MODIFIERS =
            DeferredRegister.create(Registries.PLACEMENT_MODIFIER_TYPE, GroundBurst.MODID);

    public static final DeferredHolder<PlacementModifierType<?>, PlacementModifierType<ConfigToggleFilter>> CONFIG_TOGGLE =
            PLACEMENT_MODIFIERS.register("config_toggle", () -> () -> ConfigToggleFilter.CODEC.codec());

    private GBWorldgen() {}
}
